package com.company.platform.order.application;
import com.company.platform.order.domain.*;import com.company.platform.order.domain.events.OrderEvent;import com.company.platform.order.infrastructure.*;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;
@Service public class OrderService{private final OrderRepository orders;private final TenantContextProvider tenant;private final KafkaOrderEventPublisher events;public OrderService(OrderRepository o,TenantContextProvider t,KafkaOrderEventPublisher e){orders=o;tenant=t;events=e;}
 public Order create(UUID customerId,UUID storeId,Currency currency,List<ItemCommand> commands){UUID t=tenant.currentTenantId();Order o=Order.create(t,new OrderNumber("ORD-"+Instant.now().toEpochMilli()+"-"+UUID.randomUUID().toString().substring(0,8)),customerId,storeId,currency);for(var c:commands)o.addItem(new OrderItem(null,o.id(),c.productId(),c.productSnapshot(),c.quantity(),new Money(c.amount(),currency),null));o.submit();var saved=orders.save(o);emit("OrderCreatedEvent",saved);return saved;}
 public Order confirm(UUID id){Order o=get(id);o.confirm();var s=orders.save(o);emit("OrderConfirmedEvent",s);return s;}public Order cancel(UUID id){Order o=get(id);o.cancel();var s=orders.save(o);emit("OrderCancelledEvent",s);return s;}public Order get(UUID id){return orders.findByTenantIdAndId(tenant.currentTenantId(),id).orElseThrow(()->new NoSuchElementException("order not found"));}public List<Order> byCustomer(UUID id){return orders.findByTenantIdAndCustomerId(tenant.currentTenantId(),id);}public List<Order> byStore(UUID id){return orders.findByTenantIdAndStoreId(tenant.currentTenantId(),id);}private void emit(String type,Order o){events.publish(new OrderEvent(UUID.randomUUID(),type,o.id(),o.tenantId(),Instant.now(),o));}public record ItemCommand(UUID productId,String productSnapshot,int quantity,java.math.BigDecimal amount){}
}
